# Executed inside src/build_report.py. E3 Gaussian Bayes classifier; numbers loaded from results/extE3_*.csv.
section("Extension E3: Gaussian Bayes classifier")
E3M, E3C, E3P, E3K = "results/extE3_metrics.csv", "results/extE3_confusion.csv", "results/extE3_params.csv", "results/extE3_sklearn_check.csv"
SCRIPT.update({E3M: "src/ext_E3_gaussian_bayes.py", E3C: "src/ext_E3_gaussian_bayes.py", E3P: "src/ext_E3_gaussian_bayes.py", E3K: "src/ext_E3_gaussian_bayes.py"})
e = []; a = e.append
a("### 8.3 E3: Gaussian Bayes classifier for the cycle phase\n")
a("Math note: `docs/math/E3_gaussian_bayes_classifier.md`. Features: log1p estradiol and log1p progesterone. Class priors, class means and covariances are estimated in the **training fold only**; Bayes' theorem gives the posterior; the prediction is the posterior mode. Primary model: class-specific full covariances (QDA) with empirical priors. Variants: shared covariance (LDA), diagonal covariance (naive Bayes), and equal priors. Same folds as the Phase 6b logistic regression (the comparison), same women, same bootstrap seed. There are no hyper-parameters, so no inner CV.\n")
claim(float(df(E3K).max_abs_posterior_diff.iloc[0]) < 1e-8, "E3 matches scikit-learn QDA")
a(f"**Check against scikit-learn.** On the full pooled sample ({nn('pooled')}) the posterior probabilities of my full-covariance classifier differ from `QuadraticDiscriminantAnalysis` by at most {val(E3K, dict(sample='pooled'), 'max_abs_posterior_diff', '{:.1e}', label='E3 max |posterior diff| vs sklearn QDA')}.\n")
a(f"**What the model learned** (pooled, {nn('pooled')}; descriptive fit on all rows): class priors menses/peri-ovulatory/luteal {val(E3P, dict(class_='menses'), 'prior', '{:.2f}', label='E3 prior menses')}/{val(E3P, dict(class_='peri-ov'), 'prior', '{:.2f}', label='E3 prior periov')}/{val(E3P, dict(class_='luteal'), 'prior', '{:.2f}', label='E3 prior luteal')}.\n")
a("| Class | mean log E2 | mean log P | SD log E2 | SD log P | correlation in class |\n|---|---|---|---|---|---|")
for c_ in ["menses", "peri-ov", "luteal"]: a(f"| {c_} | " + " | ".join(val(E3P, dict(class_=c_), col, "{:.2f}", label=f"E3 {c_} {col}") for col in ["mean_logE2", "mean_logP", "sd_logE2", "sd_logP", "corr"]) + " |")
table("T-E3-params", "fitted class parameters (descriptive)", E3P, "src/ext_E3_gaussian_bayes.py")
a("\nProgesterone separates the luteal class (higher mean and smaller spread); estradiol differs mostly between menses and the other two classes.\n")
a("**Out-of-fold performance** (balanced accuracy [95% CI over women]; chance 0.333; difference to logistic regression in balanced accuracy [95% CI], same women resampled; mean log loss and its change relative to a prior-only classifier that ignores the hormones, in nats):\n")
VN = {"gauss_bayes_full_empirical": "Gaussian Bayes, full cov., empirical priors (primary)", "gauss_bayes_full_equal": "Gaussian Bayes, full cov., equal priors", "gauss_bayes_shared_empirical": "Gaussian Bayes, shared cov. (LDA), empirical priors", "gauss_bayes_shared_equal": "Gaussian Bayes, shared cov., equal priors",
      "gauss_bayes_diag_empirical": "Gaussian Bayes, diagonal cov., empirical priors", "gauss_bayes_diag_equal": "Gaussian Bayes, diagonal cov., equal priors", "logreg": "logistic regression (Phase 6b)"}
for s_ in ["pooled", "long", "cross2long"]:
    rr = df(E3M)[df(E3M)["sample"] == s_].iloc[0]
    a(f"**{SMP[s_].capitalize()}** " + (f"(training {nn('cross')}; test {nn('long')})" if s_ == "cross2long" else f"({nn(s_)})") + ":\n")
    a("| Model | Balanced accuracy | Accuracy | Difference to logistic regression | Log loss (change vs prior-only) |\n|---|---|---|---|---|")
    for m_, lab in VN.items():
        w = dict(sample=s_, model=m_); ba = ci(E3M, w, "bal_acc", "{:.3f}", lo="bal_acc_lo", hi="bal_acc_hi", label=f"E3 bal acc {s_} {m_}"); acc = val(E3M, w, "acc", "{:.3f}", label=f"E3 acc {s_} {m_}")
        dl = "-" if m_ == "logreg" else ci(E3M, w, "d_bal_acc_vs_logreg", "{:+.3f}", lo="d_lo", hi="d_hi", label=f"E3 diff logreg {s_} {m_}")
        ll = "-" if m_ == "logreg" else f"{val(E3M, w, 'log_loss', '{:.3f}', label=f'E3 log loss {s_} {m_}')} ({ci(E3M, w, 'd_log_loss_vs_prior', '{:+.3f}', lo='d_ll_lo', hi='d_ll_hi', label=f'E3 d log loss {s_} {m_}')})"
        a(f"| {lab} | {ba} | {acc} | {dl} | {ll} |")
    a("")
table("T-E3", "balanced accuracy, differences to logistic regression, log loss", E3M, "src/ext_E3_gaussian_bayes.py")
pri = {s_: df(E3M).query("sample == @s_ and model == 'gauss_bayes_full_empirical'").iloc[0] for s_ in ["pooled", "long"]}; claim(all(float(pri[s_].bal_acc_lo) > 1 / 3 for s_ in pri), "primary classifier above chance")
claim(float(df(E3M).query("sample == 'long' and model == 'gauss_bayes_full_equal'").d_hi.iloc[0]) >= -1e-9 and float(df(E3M).query("sample == 'pooled' and model == 'gauss_bayes_full_equal'").d_hi.iloc[0]) > 0, 'equal-priors variant not clearly different from logistic regression'); claim(int(df(E3M).dropna(subset=['d_lo']).eval('d_lo > 0').sum()) == 0, 'no variant significantly better than logistic regression')
nlr = lambda q: agg(E3M, f"model != 'logreg' and {q}", None, "count", "{:.0f}", label=f"E3 variants {q}"); nv3 = agg(E3M, "model != 'logreg'", None, "count", "{:.0f}", label="E3 variant-sample combinations")
a(f"**Findings.** (1) The primary Gaussian Bayes classifier is clearly above chance (balanced accuracy {ci(E3M, dict(sample='pooled', model='gauss_bayes_full_empirical'), 'bal_acc', '{:.3f}', lo='bal_acc_lo', hi='bal_acc_hi', label='E3 primary pooled')} pooled, {ci(E3M, dict(sample='long', model='gauss_bayes_full_empirical'), 'bal_acc', '{:.3f}', lo='bal_acc_lo', hi='bal_acc_hi', label='E3 primary long')} longitudinal, versus 0.333), and its posterior probabilities are informative: the log loss is lower than that of the prior-only classifier (pooled change {ci(E3M, dict(sample='pooled', model='gauss_bayes_full_empirical'), 'd_log_loss_vs_prior', '{:+.3f}', lo='d_ll_lo', hi='d_ll_hi', label='E3 dll primary pooled')} nats). (2) Compared with logistic regression the primary variant is lower in balanced accuracy (pooled {ci(E3M, dict(sample='pooled', model='gauss_bayes_full_empirical'), 'd_bal_acc_vs_logreg', '{:+.3f}', lo='d_lo', hi='d_hi', label='E3 diff primary pooled')}), because empirical priors favour the common classes and the peri-ovulatory class, the smallest, is rarely predicted (recall {val(E3M, dict(sample='pooled', model='gauss_bayes_full_empirical'), 'recall_peri_ov', '{:.2f}', label='E3 recall periov primary pooled')}, against {val(E3M, dict(sample='pooled', model='gauss_bayes_full_equal'), 'recall_peri_ov', '{:.2f}', label='E3 recall periov equal pooled')} with equal priors). With equal priors, which matches the balanced-accuracy criterion and the class-balanced logistic regression, the difference to logistic regression is {ci(E3M, dict(sample='pooled', model='gauss_bayes_full_equal'), 'd_bal_acc_vs_logreg', '{:+.3f}', lo='d_lo', hi='d_hi', label='E3 diff equal pooled')} (pooled) and {ci(E3M, dict(sample='long', model='gauss_bayes_full_equal'), 'd_bal_acc_vs_logreg', '{:+.3f}', lo='d_lo', hi='d_hi', label='E3 diff equal long')} (longitudinal): no clear difference (the longitudinal interval only just reaches 0). (3) The covariance structure matters little (shared, full and diagonal give similar balanced accuracy within each prior setting). Across the {nv3} variant-sample combinations the interval of the difference to logistic regression excludes 0 in {calc('E3 n significant diffs', int(df(E3M).dropna(subset=['d_lo']).eval('(d_lo > 0) | (d_hi < 0)').sum()), '{:.0f}', E3M, 'd_lo > 0 or d_hi < 0')}; none favours the Gaussian Bayes classifier ({calc('E3 n better', int(df(E3M).dropna(subset=['d_lo']).eval('d_lo > 0').sum()), '{:.0f}', E3M, 'd_lo > 0')} comparisons).\n")
cmv = lambda mm, tr, pr: val(E3C, dict(sample="pooled", model=mm, true=tr, pred=pr), "count", "{:.0f}", label=f"E3 confusion {mm} {tr}->{pr}")
a(f"Confusion matrices, pooled ({nn('pooled')}; rows = true class, columns = predicted menses / peri-ovulatory / luteal):\n")
a("| True class | Primary (empirical priors) | Equal priors |\n|---|---|---|")
for tr in ["menses", "peri-ov", "luteal"]: a(f"| {tr} | " + " / ".join(cmv("gauss_bayes_full_empirical", tr, pr) for pr in ["menses", "peri-ov", "luteal"]) + " | " + " / ".join(cmv("gauss_bayes_full_equal", tr, pr) for pr in ["menses", "peri-ov", "luteal"]) + " |")
table("T-E3-confusion", "pooled confusion matrices of the Gaussian Bayes classifier", E3C, "src/ext_E3_gaussian_bayes.py")
a("\nAs for logistic regression (Phase 6b) the luteal phase is recognised best and menses and peri-ovulation are confused with each other. Leakage checks as before: folds are by woman (asserted), priors, means and covariances come from the training fold only, and the cross-sectional and longitudinal women are disjoint.\n")
EXT.append("\n".join(e))
